    {
      "id": 1,
      "claim": "For a pure substance the total mass equals the number of its molecules multiplied by the invariant molecular mass (molecular mass of H₂O is constant).",
      "evidence": "Definition of mass in classical physics; for a given chemical species each molecule has the same mass, so M = N·m₀.",
      "weight": 0.35,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "During evaporation no H₂O molecules are created or destroyed; the process is a physical phase change only.",
      "evidence": "Law of conservation of matter for physical changes; evaporation merely changes intermolecular spacing, not chemical identity.",
      "weight": 0.30,
      "depends_on": []
    },
    {
      "id": 3,
      "claim": "Therefore the number of H₂O molecules (N) remains constant when 1 g of liquid water turns into vapor.",
      "evidence": "Direct consequence of step 2: if no molecules are created or lost, N is unchanged.",
      "weight": 0.20,
      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "Since both the molecular mass (step 1) and the molecule count (step 3) stay the same, the total mass stays the same after evaporation.",
      "evidence": "Combine step 1 (M = N·m₀) with step 3 (N constant) → M unchanged.",
      "weight": 0.15,
      "depends_on": [1, 3]
    }
  ],
  "answer": "C",
  "confidence": 0.98,
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "Temperature may change during evaporation; mass does not depend on temperature in a closed system."
    },
    {
      "answer": "B",
      "reason_rejected": "External pressure can vary; mass conservation is independent of pressure."
    },
    {
      "answer": "D",
      "reason_rejected": "Inter‑molecular distances increase dramatically when water vapor forms, so this statement is false for the process."
    }
  ]
}
